(() => {
  const game = window.DRIFTWING;
  const spawns = game.ctx.systems.spawns;
  window.__dwCheck = (name, ok, detail) => {
    if (!ok) console.error(`[weatherVolume check] ${name} failed: ${detail}`);
    return `${ok ? 'PASS' : 'FAIL'} ${name}: ${detail}`;
  };
  if (!spawns.debug) throw new Error('engine-weatherVolume needs the spawns dev hook (a dev server, or a build with ?dev=1)');
  const engine = spawns.manager.registry.get('weatherVolume');
  if (!engine) throw new Error('the weatherVolume engine is not registered');
  const callouts = ['{name} {distance} {direction}.', '{name} ahead, {eta}.', 'Weather check: {name}.'];
  const preset = (id, name, params, { heavy = false, lure = null, lod = { near: 2500, mid: 9000, far: 30000 }, audio = null } = {}) => Object.freeze({
    id, name, category: 'weather', kind: 'event', rarity: 'common', heavy,
    candidates: { cellSize: 6000, bucketSeconds: 600, chance: 0.1 },
    filters: { biomes: null, timeOfDay: null, altitude: null, weather: null },
    engines: [{ engine: 'weatherVolume', params }],
    lod, lure, wind: [], audio,
    journal: { title: name, description: 'A weatherVolume engine test fixture.' },
    discovery: { radius: 3000, requireInView: true },
    callouts,
    lifetime: { duration: [900, 900], despawn: { distance: 20000, hysteresis: 3000, outOfViewSeconds: 30 } },
  });
  const presets = [
    preset('wxSupercell', 'Test supercell', {
      form: 'tower', base: 900, height: 9000, radius: 2600, puffs: 150, storm: 0.7, formSeconds: 0,
      anvil: { radius: 8500, thickness: 1500, lean: 2600 },
      overshoot: 0.6,
      wallCloud: { radius: 900, drop: 380, offset: -700, rotation: 8 },
      rain: [{ offset: [700, 1400], radius: 1500, density: 0.8, downdraft: 6, outflow: 10 }],
      wind: { updraft: 6, turbulence: 0.5 },
    }, { heavy: true, lure: { type: 'anvil', height: 11000, width: 17000, color: 0xdfe3ea }, lod: { near: 6000, mid: 22000, far: 60000 }, audio: { recipe: 'thunder', params: {} } }),
    preset('wxLenticular', 'Test lenticular', {
      form: 'lens', base: 1500, radius: 1800, aspect: 0.5, thickness: 200, layers: 3, gap: 150, formSeconds: 0,
      wind: { wave: { lift: 4, sink: 3, rotor: 0.5 } },
    }),
    preset('wxFogBank', 'Test fog bank', { form: 'bank', length: 4200, width: 1300, height: 300, puffs: 90, formSeconds: 0 }),
    preset('wxMist', 'Test mist', { form: 'mist', radius: 240, height: 420, rise: 8, formSeconds: 0 }),
    preset('wxCloudSea', 'Test cloud sea', { form: 'sheet', base: 250, radius: 4200, thickness: 160, puffs: 160, formSeconds: 0 }),
    preset('wxNoctilucent', 'Test noctilucent', { form: 'sheet', base: 7000, radius: 9000, thickness: 90, puffs: 140, ripple: 0.8, tint: 0xcfe4ff, glow: { color: 0x9fd4ff, strength: 1.2, when: 'always' }, formSeconds: 0 }),
    preset('wxInside', 'Test inside', { form: 'sheet', baseMode: 'anchor', base: 0, radius: 1600, thickness: 160, puffs: 120, formSeconds: 0 }),
    preset('wxShower', 'Test shower', {
      form: 'cumulus', base: 1100, height: 1400, radius: 1100, puffs: 50, storm: 0.6, formSeconds: 0,
      rain: [{ offset: [0, 0], radius: 900, density: 0.9, downdraft: 8, outflow: 12 }],
    }),
    preset('wxSquall', 'Test snow squall', {
      form: 'bank', base: 0, length: 3000, width: 1800, height: 700, puffs: 70, wall: 0.4, storm: 0.4, tint: 0xeef3f8, formSeconds: 0, canopyRain: 0.6,
      rain: [{ offset: [0, 0], radius: 1400, density: 0.85, kind: 'snow', top: 700 }],
    }),
  ];
  for (const entry of presets) if (!spawns.manager.getPreset(entry.id)) spawns.debug.addPreset(entry);
  window.__dwWx = { engine, ids: [] };
  return window.__dwCheck('setup: engine registered, presets added', true, JSON.stringify({ presets: presets.map((entry) => entry.id) }));
})()

