(() => {
  const { ctx } = window.DRIFTWING;
  ctx.setPhotoMode(true);
  // Frames a spawn from above the craft: target is the anchor lifted by focus metres.
  window.__dwWx.frame = (id, focus, lift = 120) => {
    const { ctx: gameCtx, state } = window.DRIFTWING;
    const part = gameCtx.systems.spawns.manager.getParts(id)[0];
    const player = state.player.position;
    const position = { x: player.x, y: player.y + lift, z: player.z };
    const target = { x: part.anchor.x, y: part.anchor.y + focus, z: part.anchor.z };
    return gameCtx.systems.camera.setFreeCameraPose({ position, target });
  };
  return 'photo mode';
})()

