(() => {
  const { ctx } = window.DRIFTWING;
  const engine = window.__dwWx.engine;
  const original = engine.update;
  const meter = { cpu: 0, calls: 0 };
  engine.update = function measuredUpdate(instance, dt, engineCtx) {
    const start = performance.now();
    original.call(engine, instance, dt, engineCtx);
    meter.cpu += performance.now() - start;
    meter.calls++;
  };
  window.__dwWx.meter = meter;
  window.__dwWx.restoreUpdate = () => { engine.update = original; };
  // A window samples frames (state.frame) and wall time; readings are { frames, frameMs, cpuMsPerFrame, triangles }.
  window.__dwWx.window = () => ({ frame: window.DRIFTWING.state.frame, time: performance.now(), cpu: meter.cpu, calls: meter.calls });
  window.__dwWx.read = (start) => {
    const now = window.__dwWx.window();
    const frames = Math.max(1, now.frame - start.frame);
    return { frames, frameMs: Math.round(((now.time - start.time) / frames) * 100) / 100, cpuMsPerFrame: Math.round(((now.cpu - start.cpu) / frames) * 1000) / 1000, triangles: ctx.renderer.info.render.triangles, drawCalls: ctx.renderer.info.render.drawCalls };
  };
  const sun = ctx.state.time.sunDirection;
  window.__dwWx.lookAhead = () => {
    const player = window.DRIFTWING.state.player;
    const forward = player.forward;
    const position = { x: player.position.x, y: player.position.y + 120, z: player.position.z };
    return ctx.systems.camera.setFreeCameraPose({ position, target: { x: position.x + forward.x * 1000, y: position.y + 250, z: position.z + forward.z * 1000 } });
  };
  window.__dwWx.lookAhead();
  window.__dwWx.start = window.__dwWx.window();
  return JSON.stringify({ metering: true, sunY: Math.round(sun.y * 100) / 100 });
})()

