(() => {
  const { ctx } = window.DRIFTWING;
  const memory = ctx.renderer.info.memory;
  const baseline = window.__dwWx.baseline;
  const stats = window.__dwWx.engine.stats();
  const modifiers = ctx.systems.sky.getModifierState().ids.join(',');
  const now = { geometries: memory.geometries, textures: memory.textures, attributes: memory.attributes, wind: ctx.wind.sourceCount, modifiers };
  const log = ctx.systems.spawns.getStats().memory.log.slice(-6).map((entry) => ({ id: entry.id, geometries: [entry.before.geometries, entry.afterCreate.geometries, entry.afterDispose.geometries] }));
  const ok = now.geometries === baseline.geometries && now.textures === baseline.textures && now.attributes === baseline.attributes && now.wind === baseline.wind && stats.instances === 0 && modifiers === baseline.modifiers;
  return window.__dwCheck('dispose returns GPU memory and wind sources to the baseline', ok, JSON.stringify({ baseline, now, stats, leaks: ctx.systems.spawns.getStats().leaks, log }));
})()

