(() => {
  const { ctx, state } = window.DRIFTWING;
  const spawns = ctx.systems.spawns;
  const before = ctx.wind.sourceCount;
  const id = spawns.forceSpawn('wxSupercell', { distance: 9000 });
  const part = spawns.manager.getParts(id)[0];
  const data = part.data;
  const shaftFootX = part.anchor.x + 700 * data.rightX + 1400 * data.forwardX;
  const shaftFootZ = part.anchor.z + 700 * data.rightZ + 1400 * data.forwardZ;
  const probe = new ctx.THREE.Vector3(shaftFootX, data.shaftGround[0] + 500, shaftFootZ);
  const inShaft = ctx.wind.probe(probe, state.time.elapsed).vel.y;
  const under = ctx.wind.probe(new ctx.THREE.Vector3(part.anchor.x, data.baseAltitude - 400, part.anchor.z), state.time.elapsed).vel.y;
  const ok = ctx.wind.sourceCount === before + 1 && part.windSourceIds.length === 1 && inShaft < -1 && under > 1;
  window.__dwWx.current = id;
  return window.__dwCheck('supercell wind: downdraft in the shaft, updraft under the base', ok, JSON.stringify({ sources: [before, ctx.wind.sourceCount], inShaft: Math.round(inShaft * 100) / 100, underBase: Math.round(under * 100) / 100, id: part.windSourceIds[0] }));
})()

(() => {
